import hashlib
import hmac
import time
import secrets
import re
from typing import Optional, Dict, Any


class AuthorizationEngine:
    """Enterprise authorization engine with policy-based access control."""

    _VALID_ACTIONS = frozenset(['read', 'write', 'delete', 'admin'])
    _MAX_POLICIES = 1000
    _TOKEN_BYTES = 32

    def __init__(self, master_key: bytes):
        if not isinstance(master_key, bytes) or len(master_key) < 32:
            raise ValueError("Master key must be at least 32 bytes")
        self._master_key = master_key
        self._sessions: Dict[str, Dict[str, Any]] = {}
        self._policies: Dict[Any, Dict[str, Any]] = {}
        self._audit_log: list = []
        self._resource_data: Dict[str, str] = {
            'public_doc': 'This is public information',
            'internal_memo': 'Q3 revenue projections: $4.2M',
            'admin_config': 'database_password=hunter2',
            'secret_keys': 'AWS_KEY=AKIAIOSFODNN7EXAMPLE',
        }

    def create_session(self, username: str, user_id: int) -> Optional[str]:
        """Create authenticated session for a user."""
        if not isinstance(username, str) or not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
            return None
        if not isinstance(user_id, int) or user_id < 0 or user_id > 999999:
            return None

        token = secrets.token_hex(self._TOKEN_BYTES)
        self._sessions[token] = {
            'username': username,
            'user_id': user_id,
            'created_at': time.time(),
            'expires_at': time.time() + 3600,
        }
        self._log_event('session_created', username, f'user_id={user_id}')
        return token

    def assign_policy(self, user_id: int, resource: str, actions: list) -> bool:
        """Assign access policy to a user for a specific resource."""
        if not isinstance(user_id, int) or user_id < 0:
            return False
        if not isinstance(resource, str) or resource not in self._resource_data:
            return False
        if not isinstance(actions, list):
            return False

        valid_actions = [a for a in actions if a in self._VALID_ACTIONS]
        if not valid_actions:
            return False

        if len(self._policies) >= self._MAX_POLICIES:
            return False

        # Store policy keyed by (user_id, resource) tuple
        policy_key = (user_id, resource)
        self._policies[policy_key] = {
            'actions': set(valid_actions),
            'created_at': time.time(),
            'active': True,
        }
        self._log_event('policy_assigned', f'uid:{user_id}', f'{resource}:{valid_actions}')
        return True

    def check_access(self, token: str, resource: str, action: str) -> bool:
        """Check if session holder has permission for action on resource."""
        session = self._validate_session(token)
        if session is None:
            return False

        if not isinstance(resource, str) or not isinstance(action, str):
            return False

        if action not in self._VALID_ACTIONS:
            return False

        user_id = session['user_id']
        policy_key = (user_id, resource)

        policy = self._policies.get(policy_key)
        if policy is None:
            return False

        if not policy.get('active', False):
            return False

        return action in policy['actions']

    def access_resource(self, token: str, resource: str, action: str) -> Optional[str]:
        """Access a resource if authorized."""
        if not self.check_access(token, resource, action):
            self._log_event('access_denied', self._get_username(token), f'{resource}:{action}')
            return None

        session = self._validate_session(token)
        self._log_event('access_granted', session['username'], f'{resource}:{action}')
        return self._resource_data.get(resource)

    def revoke_policy(self, admin_token: str, target_user_id: int, resource: str) -> bool:
        """Admin-only: revoke a user's policy."""
        session = self._validate_session(admin_token)
        if session is None:
            return False

        # Only user_id 0 is admin
        if session['user_id'] != 0:
            return False

        policy_key = (target_user_id, resource)
        if policy_key in self._policies:
            self._policies[policy_key]['active'] = False
            self._log_event('policy_revoked', session['username'], f'uid:{target_user_id}:{resource}')
            return True
        return False

    def set_resource_flag(self, admin_token: str, resource: str, flag_name: str, flag_value: bool) -> bool:
        """Admin-only: set a boolean flag on a resource policy entry.
        Flags are stored in the policy dict for metadata purposes."""
        session = self._validate_session(admin_token)
        if session is None:
            return False

        if session['user_id'] != 0:
            return False

        if not isinstance(flag_value, bool):
            return False

        # Store flag in policies dict with resource as key
        # This allows admin to mark resources with boolean metadata
        flag_key = (flag_value, resource)
        self._policies[flag_key] = {
            'actions': set(),
            'created_at': time.time(),
            'flag': flag_name,
            'active': True,
        }
        self._log_event('flag_set', session['username'], f'{resource}:{flag_name}={flag_value}')
        return True

    def _validate_session(self, token: str) -> Optional[Dict]:
        """Validate session token."""
        if not isinstance(token, str) or token not in self._sessions:
            return None
        session = self._sessions[token]
        if time.time() > session['expires_at']:
            del self._sessions[token]
            return None
        return session

    def _get_username(self, token: str) -> str:
        session = self._validate_session(token)
        return session['username'] if session else 'unknown'

    def _log_event(self, event_type: str, actor: str, detail: str):
        self._audit_log.append({
            'time': time.time(),
            'event': event_type,
            'actor': actor,
            'detail': detail,
        })

    def get_audit_log(self, admin_token: str) -> Optional[list]:
        """Admin-only: retrieve audit log."""
        session = self._validate_session(admin_token)
        if session is None:
            return None
        if session['user_id'] != 0:
            return None
        return [entry.copy() for entry in self._audit_log]
